-- transition_goal
update public.fields set verification_status='verified_against_standard', verification_quote='The organization should initially define its goals, i.e. what it seeks to achieve by transitioning to a circular economy value creation model. This goal definition process can include considerations on reductions in resource inflows and outflows, energy consumption and water consumption, as well as other approaches to improve the efficient use of resources. — printed p.5', verification_note='md-verified 2026-09-09 - source: ISO/FDIS 59010:2024(en), FINAL DRAFT International Standard (a ballot draft, NOT the published ISO 59010) - §4.1, printed p.5 = PDF p.13, confirmed on the rendered page [VA-OCR]', verified_at=now() where id='1d797b75-4fc8-4a1b-8a06-68e8b7c4ddf3' and verification_status not in ('verified_against_standard','corrected');

-- goal_measurable
update public.fields set verification_status='verified_against_standard', verification_quote='To help set measurable goals, an organization can conduct an assessment by reviewing and mapping all its activities and interactions within and between its value chains and broader value network. — printed p.5', verification_note='md-verified 2026-09-09 - source: ISO/FDIS 59010:2024(en), FINAL DRAFT International Standard (a ballot draft, NOT the published ISO 59010) - §4.1, printed p.5 = PDF p.13, confirmed on the rendered page. CAVEAT: the printed modality is "can", not "shall"/"should"; the field is nevertheless is_required=true and gate CR-002 tests it == true - see STAGED R-5 [VA-OCR]', verified_at=now() where id='c23ee82a-861e-427b-92a9-2cc8efcfb6b9' and verification_status not in ('verified_against_standard','corrected');

