update public.fields set verification_status='verified_against_standard', verification_quote='In addition to the above business elements, relevant enablers should be identified and understood for how their availability influences business elements. — printed p.7', verification_note='md-verified 2026-09-09 - source: ISO/FDIS 59010:2024(en), FINAL DRAFT International Standard (a ballot draft, NOT the published ISO 59010) - §4.2 (last paragraph), printed p.7 = PDF p.15, confirmed on the rendered page [VA-OCR]', verified_at=now() where id='006399e7-4029-46fa-a823-2bdf9bb0fc3a' and verification_status not in ('verified_against_standard','corrected');

