-- sufficient_enablers
update public.fields set verification_status='verified_against_standard', verification_quote='These enablers provide the necessary infrastructure and support to foster circular initiatives. They can include shared infrastructure, circular suppliers, academic partnerships, research and development, etc. Therefore, when conducting this mapping activity, organizations should focus on their relationships and assess whether there are sufficient enablers or if others need to be developed. — printed p.7', verification_note='md-verified 2026-09-09 - source: ISO/FDIS 59010:2024(en), FINAL DRAFT International Standard (a ballot draft, NOT the published ISO 59010) - §4.3, printed p.7 = PDF p.15, confirmed on the rendered page [VA-OCR]', verified_at=now() where id='a67c8c64-2592-4678-91e7-351e6497b9cb' and verification_status not in ('verified_against_standard','corrected');

-- boundary_defined
update public.fields set verification_status='verified_against_standard', verification_quote='Setting the boundary (e.g. a company or group of companies within the value network) will help clarify the scope of actions necessary to achieve an organization''s goals. This boundary applies to all of the following clauses and subclauses. — printed p.7', verification_note='md-verified 2026-09-09 - source: ISO/FDIS 59010:2024(en), FINAL DRAFT International Standard (a ballot draft, NOT the published ISO 59010) - §4.4 (opening), printed p.7 = PDF p.15, confirmed on the rendered page [VA-OCR]', verified_at=now() where id='243dda47-b882-4e47-8261-345e407ad633' and verification_status not in ('verified_against_standard','corrected');

-- boundary_scope
update public.fields set verification_status='verified_against_standard', verification_quote='The organization should define a boundary and scope of actions after gaining a clear initial picture of its operational context. The boundary should include all relevant activities, locations, types of solutions and value networks. It should include the portion of the economic system within which the organization operates, collaborates or exercises influence (e.g. supply chain, supply partners), and within which it can drive the circular flow of resources, sustainable development and assess performance. — printed p.7', verification_note='md-verified 2026-09-09 - source: ISO/FDIS 59010:2024(en), FINAL DRAFT International Standard (a ballot draft, NOT the published ISO 59010) - §4.4, printed p.7 = PDF p.15, confirmed on the rendered page [VA-OCR]', verified_at=now() where id='5cab4447-5814-4731-a715-fe42e81eeba4' and verification_status not in ('verified_against_standard','corrected');

-- boundary_aligned_with_influence
update public.fields set verification_status='verified_against_standard', verification_quote='Theoretically, a value chain and value network can be extensive. However, when setting the boundary, it should align with the boundary of the organization''s ambition. | To set an appropriate boundary, an organization should consider its sphere of influence. Each organization can have different capacities to influence different aspects of circularity within its value network. — printed p.7 and p.8', verification_note='md-verified 2026-09-09 - source: ISO/FDIS 59010:2024(en), FINAL DRAFT International Standard (a ballot draft, NOT the published ISO 59010) - §4.4, printed p.7 = PDF p.15 (first passage) and printed p.8 = PDF p.16 (second passage), both confirmed on the rendered pages. "sphere of influence" is defined at §3.15, printed p.4 = PDF p.12 [VA-OCR]', verified_at=now() where id='e56affce-2a53-4368-8cae-3e3686eda121' and verification_status not in ('verified_against_standard','corrected');


