-- circularity_performance_assessed
update public.fields set verification_status='verified_against_standard', verification_quote='To measure and assess the circular performance, ISO 59020 provides a taxonomy of circularity indicators to measure resource flows and their impacts within a system under study (described as the "system in focus"). | Once the current performance is evaluated, the next step is to determine a strategy of improvement as described in Clause 5. The selected KPIs should be continually monitored and evaluated as described in Clause 8. — printed p.8 and p.9', verification_note='md-verified 2026-09-09 - source: ISO/FDIS 59010:2024(en), FINAL DRAFT International Standard (a ballot draft, NOT the published ISO 59010) - §4.5, printed p.8 = PDF p.16 (first passage) and printed p.9 = PDF p.17 (second passage), both confirmed on the rendered pages. NR CAVEAT: the indicator taxonomy itself lives in ISO 59020, which is a separate document [VA-OCR]', verified_at=now() where id='bfc64e0c-c18d-43e1-8484-783bee8d0aa0' and verification_status not in ('verified_against_standard','corrected');

-- indicator_category
update public.fields set verification_status='verified_against_standard', verification_quote='ISO 59020 categorizes these indicators as follows: | Resource inflows: The resource inflow circularity indicators represent the circularity performance of resources that flow through the system boundary into the system in focus. | Resource outflows: The resource outflow circularity indicators represent the circularity performance of resources that flow out of the boundary of the system in focus. | Energy: The energy circularity indicators represent the fraction of energy used by the system in focus that is renewable energy. | Water: This is an important resource and a focus of a circular economy. | Economic: The application of economic-related circularity indicators is of high importance for an organization. — printed p.8', verification_note='md-verified 2026-09-09 - source: ISO/FDIS 59010:2024(en), FINAL DRAFT International Standard (a ballot draft, NOT the published ISO 59010) - §4.5, printed p.8 = PDF p.16, confirmed on the rendered page; the 5 enum values reproduce the 5 printed dashes exactly. CAVEAT: Figure 4 (printed p.20 = PDF p.28) shows a DIFFERENT category set for the same purpose - "Resource (inflows/outflows), Waste and emissions, Energy, Water, Economic and other indicators" - see STAGED R-8 [VA-OCR]', verified_at=now() where id='79ed1c19-22d5-4209-9463-500d8c7657a1' and verification_status not in ('verified_against_standard','corrected');

